/**
 * Collection-coverage disclosure.
 *
 * The most dangerous output this report can produce is a confident all-clear generated by
 * looking at nothing. In practice a run against an overloaded node can have most of its checks
 * fail with "Could not run: the wait operation timed out", and the report used to render
 * "100% average health", "Nothing to action", and a subject line of "[OK]". Every failed
 * check had mapped to Info, and Info does not affect the score — so wholesale collection
 * failure was indistinguishable from a healthy node.
 *
 * `error` and `skipped` both display as Info but mean opposite things: `skipped` is a
 * deliberate, understood absence (no Windows credential, covered by the DMV fallbacks),
 * while `error` means the check COULD NOT LOOK. These tests hold that distinction.
 */
import { test } from "node:test";
import assert from "node:assert/strict";
import { CATALOG, toFinding, generateHtmlReport, scoreFindings, coverageOf, isDegraded, COVERAGE_DEGRADED_RATIO } from "../src/dbatools.js";

type Raw = Parameters<typeof toFinding>[0];

/** Build N raw checks, the first `errored` of which failed to collect. */
function run(total: number, errored: number, skipped = 0): Raw[] {
  return CATALOG.slice(0, total).map((c, i) => {
    const base = {
      category: c[0] as string, label: c[1] as string, command: c[2] as string,
      priority: c[5] as string, rows: 0, shown: 0, data: [],
    };
    if (i < errored) return { ...base, status: "error", error: "The wait operation timed out" };
    if (i < errored + skipped) return { ...base, status: "skipped" };
    return { ...base, status: "pass" };
  });
}

function render(raw: Raw[]) {
  const findings = raw.map(toFinding);
  const score = scoreFindings(findings);
  const coverage = coverageOf(findings, raw);
  const html = generateHtmlReport("2026-01-05T00:00:00Z", [{
    instance: "region1-node2", computer: "REGION1-NODE2", sql_instance: "REGION1-NODE2",
    overall_health: score.overall, status_counts: score.counts, categories: score.categories,
    findings, coverage,
  }] as Parameters<typeof generateHtmlReport>[1]);
  return { coverage, html, text: html.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ") };
}

test("a mostly-errored run is no longer rendered as an all-clear", () => {
  // 45 of 60 errored — the shape that produced "100% average health / Nothing to action".
  const { coverage, text } = render(run(60, 45));
  assert.equal(coverage.errored, 45);
  assert.ok(isDegraded(coverage), "45/60 must count as degraded coverage");
  assert.match(text, /INCOMPLETE/, "a degraded run must be labelled INCOMPLETE in the body");
  assert.match(text, /45 of 60 checks could not run/, "the report must state how much did not run");
  assert.doesNotMatch(text, /Nothing to action — no failures/,
    "must not claim there is nothing to action when it could not look");
});

test("a healthy run is still reported cleanly - no crying wolf", () => {
  const { coverage, text } = render(run(60, 0));
  assert.equal(coverage.errored, 0);
  assert.ok(!isDegraded(coverage));
  assert.doesNotMatch(text, /INCOMPLETE/, "a full run must not be labelled incomplete");
  assert.doesNotMatch(text, /could not run/, "nothing should claim a collection failure");
});

test("a couple of flaky checks do not turn every weekly mail into a warning", () => {
  // Below the ratio: still reported, but not escalated.
  const below = Math.max(0, Math.floor(60 * COVERAGE_DEGRADED_RATIO) - 1);
  const { coverage, text } = render(run(60, below));
  assert.equal(coverage.errored, below);
  assert.ok(!isDegraded(coverage), `${below}/60 must stay below the degraded threshold`);
  assert.doesNotMatch(text, /INCOMPLETE/);
  // ...but the count is still visible, so it is never silently swallowed.
  if (below > 0) assert.match(text, new RegExp(`${below} could not run`));
});

test("skipped is not the same as errored", () => {
  // No Windows credential skips the OS/CIM checks by design; the DMV fallbacks cover them.
  // That must never read as a collection failure.
  const { coverage, text } = render(run(60, 0, 20));
  assert.equal(coverage.skipped, 20);
  assert.equal(coverage.errored, 0, "skipped must not be counted as errored");
  assert.ok(!isDegraded(coverage), "a deliberate skip is not degraded coverage");
  assert.doesNotMatch(text, /INCOMPLETE/);
});

test("the health percentage is scoped to what actually returned data", () => {
  const { coverage } = render(run(60, 45));
  assert.equal(coverage.scored, 15, "only the checks that returned data may be scored");
  assert.ok(coverage.scored < coverage.total);
});
